#!/usr/bin/env node

import { execFileSync, execSync } from 'node:child_process';
import { cpSync, existsSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const BUNDLE = join(ROOT, 'bundle');
const DIST = join(ROOT, 'frontend', 'dist', 'snip-frontend', 'browser');
const PUSH = process.argv.includes('--push');

const run = (command, args) => execFileSync(command, args, { cwd: ROOT, stdio: 'inherit' });
const capture = (command, args) => execFileSync(command, args, { cwd: ROOT, encoding: 'utf8' }).trim();
const npm = (args) => execSync(`npm ${args}`, { cwd: ROOT, stdio: 'inherit' });

console.log('> Updating source submodules...');
run('git', ['submodule', 'update', '--init', '--remote', 'backend', 'frontend', 'cli']);

console.log('> Building frontend...');
npm(`--prefix "${join(ROOT, 'frontend')}" install --no-audit --no-fund`);
npm(`--prefix "${join(ROOT, 'frontend')}" run build`);
if (!existsSync(join(DIST, 'index.html'))) {
  throw new Error(`Frontend build output not found at ${DIST}`);
}

console.log('> Assembling bundle...');
rmSync(join(BUNDLE, 'public'), { recursive: true, force: true });
for (const file of ['server.js', 'cli.js']) rmSync(join(BUNDLE, file), { force: true });
cpSync(join(ROOT, 'backend', 'server.js'), join(BUNDLE, 'server.js'));
cpSync(join(ROOT, 'cli', 'cli.js'), join(BUNDLE, 'cli.js'));
cpSync(DIST, join(BUNDLE, 'public'), { recursive: true });

writeFileSync(join(BUNDLE, '.env'), '# Generated by build-bundle.mjs\nPUBLIC_DIR=./public\n');
writeFileSync(join(BUNDLE, 'package.json'), `${JSON.stringify({
  name: 'snip-bundle',
  version: '1.0.0',
  private: true,
  scripts: { start: 'bun server.js' },
}, null, 2)}\n`);
writeFileSync(join(BUNDLE, 'Dockerfile'), [
  'FROM oven/bun:1-alpine',
  'WORKDIR /app',
  'COPY . .',
  'ENV PORT=3000',
  'EXPOSE 3000',
  'CMD ["bun", "server.js"]',
  '',
].join('\n'));
writeFileSync(join(BUNDLE, '.dockerignore'), [
  '.git', '.gitignore', 'node_modules', 'npm-debug.log', 'Dockerfile', '.dockerignore', 'README.md', '',
].join('\n'));
writeFileSync(join(BUNDLE, 'railway.json'), `${JSON.stringify({
  '$schema': 'https://railway.com/railway.schema.json',
  build: { builder: 'DOCKERFILE', dockerfilePath: 'Dockerfile' },
  deploy: { restartPolicyType: 'ON_FAILURE', restartPolicyMaxRetries: 3 },
}, null, 2)}\n`);

run('git', ['-C', BUNDLE, 'add', '-A']);
if (capture('git', ['-C', BUNDLE, 'diff', '--cached', '--name-only'])) {
  run('git', ['-C', BUNDLE, 'commit', '-m', 'Rebuild bundle from source branches']);
  if (PUSH) run('git', ['-C', BUNDLE, 'push', 'origin', 'HEAD:bundle']);
  console.log('> Bundle updated.');
} else {
  console.log('> Bundle unchanged.');
}

run('git', ['add', '--', 'backend', 'frontend', 'cli', 'bundle']);
if (capture('git', ['diff', '--cached', '--name-only', '--', 'backend', 'frontend', 'cli', 'bundle'])) {
  run('git', ['commit', '-m', 'Bump submodule pointers (bundle release)']);
  if (PUSH) run('git', ['push']);
  console.log('> Superproject pointers bumped.');
} else {
  console.log('> Superproject pointers unchanged.');
}

console.log(PUSH ? 'Bundle rebuilt, committed, and pushed.' : 'Bundle rebuilt and committed locally.');
